//! Types of the results of the built-in scalar functions, as the reference
//! file of each dialect gives them (keys `type` and `nulls` of a function),
//! from the calls generated by `probe calls` and measured on each local
//! image of the dialect. A type is one of:
//!
//! - a type of its own, whatever the arguments (`int`, `text`, `bytes`...);
//! - a string, of bytes when one of the arguments at some positions is a
//!   byte string, of characters otherwise (`CONCAT`, `LOWER`...);
//! - a type per period of versions, when the servers changed it
//!   (`[int, "8.0.24", bigint]`).
//!
//! A function without `type` gives a value of a type unknown to Prisme,
//! which depends on its arguments otherwise (`ROUND`, `COALESCE`...). The
//! result of a function of MySQL that gives a `JSON` is read as a `JSON`
//! column is: compared by the rules of JSON in `IN` from 8.0.17, read as a
//! boolean as true unless it is the number 0 from 8.0.17 (`emit::json`,
//! `emit::truth`).

use prisme_plan::Expr;
use prisme_types::{BinaryType, DataType, FloatType, IntegerSize, IntegerType, TextType};
use serde::Deserialize;

use crate::versions::Version;

/// Type of the result of a built-in function, in its dialect.
#[derive(Debug, Clone, PartialEq, Eq, Deserialize)]
#[serde(try_from = "RawResultType")]
pub(crate) struct ResultType {
    /// Type of the first versions.
    first: Shape,
    /// Each version from which another type holds, in order, with that type.
    changes: Vec<(Version, Shape)>,
}

/// Type of the result of a function in a period of versions.
#[derive(Debug, Clone, PartialEq, Eq)]
enum Shape {
    /// The same type whatever the arguments.
    Fixed(DataType),
    /// A string of bytes when one of the arguments at these positions is a
    /// byte string, or when they are all the literal `NULL`; of characters
    /// otherwise; unknown when one of them is of a type unknown to Prisme.
    String(Positions),
}

/// Positions of arguments, from 1.
#[derive(Debug, Clone, PartialEq, Eq)]
enum Positions {
    /// These positions.
    At(Vec<usize>),
    /// This position and the following ones.
    From(usize),
}

/// When the result of a function is `NULL`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default, Deserialize)]
#[serde(rename_all = "snake_case")]
pub(crate) enum Nulls {
    /// Whatever the arguments.
    #[default]
    Any,
    /// When one of the arguments may be `NULL`.
    Args,
    /// Never.
    Never,
}

impl ResultType {
    /// Type of the result of a call with `args`, in `version`.
    pub(crate) fn data_type(&self, args: &[Expr], version: Version) -> DataType {
        let shape = (self.changes.iter().rev())
            .find(|(since, _)| *since <= version)
            .map_or(&self.first, |(_, shape)| shape);
        match shape {
            Shape::Fixed(data_type) => data_type.clone(),
            Shape::String(positions) => string(args, positions),
        }
    }

    /// Versions from which the type changes.
    pub(crate) fn versions(&self) -> impl Iterator<Item = Version> + '_ {
        self.changes.iter().map(|(since, _)| *since)
    }
}

impl Nulls {
    /// Tells whether the result of a call with `args` may be `NULL`.
    pub(crate) fn nullable(self, args: &[Expr]) -> bool {
        match self {
            Self::Any => true,
            Self::Args => args.iter().any(|arg| arg.ty.nullable),
            Self::Never => false,
        }
    }
}

impl Positions {
    /// Tells whether the argument at `position`, from 1, is one of these.
    fn contains(&self, position: usize) -> bool {
        match self {
            Self::At(positions) => positions.contains(&position),
            Self::From(first) => position >= *first,
        }
    }
}

/// String given by a function of `args`, of bytes after the arguments at
/// `positions` (`crates/probe/cases/string-kinds.txt`).
fn string(args: &[Expr], positions: &Positions) -> DataType {
    let types: Vec<&DataType> = (args.iter().enumerate())
        .filter(|(index, _)| positions.contains(index + 1))
        .map(|(_, arg)| &arg.ty.data_type)
        .collect();
    let bytes = types.iter().any(|data_type| {
        matches!(
            data_type,
            DataType::Binary(_)
                | DataType::Hybrid { .. }
                | DataType::Bit { .. }
                | DataType::Geometry
        )
    });
    // `CONCAT(NULL)` is a byte string, `CONCAT(NULL, 'a')` a character one.
    let nulls = !types.is_empty() && types.iter().all(|data_type| **data_type == DataType::Null);
    if bytes || nulls {
        return bytes_type();
    }
    if (types.iter()).any(|data_type| matches!(data_type, DataType::Unknown | DataType::Other(_))) {
        return DataType::Unknown;
    }
    text_type()
}

/// Character string of unknown length, character set and collation.
fn text_type() -> DataType {
    DataType::Text(TextType {
        length: None,
        fixed: false,
        charset: None,
        collation: None,
    })
}

/// Byte string of unknown length.
fn bytes_type() -> DataType {
    DataType::Binary(BinaryType {
        length: None,
        fixed: false,
    })
}

/// Type named in a reference file.
fn named(name: &str) -> Result<DataType, String> {
    let integer = |size, unsigned| DataType::Integer(IntegerType { size, unsigned });
    Ok(match name {
        "int" => integer(IntegerSize::Int, false),
        "int unsigned" => integer(IntegerSize::Int, true),
        "bigint" => integer(IntegerSize::Big, false),
        "bigint unsigned" => integer(IntegerSize::Big, true),
        "double" => DataType::Float(FloatType::Double),
        "date" => DataType::Date,
        "year" => DataType::Year,
        "json" => DataType::Json,
        "geometry" => DataType::Geometry,
        "text" => text_type(),
        "bytes" => bytes_type(),
        "uuid" => DataType::Other("UUID".to_string()),
        _ => return Err(format!("unknown result type {name:?}")),
    })
}

/// Type as written in a reference file.
#[derive(Deserialize)]
#[serde(untagged)]
enum RawResultType {
    /// `int`, `text`...
    Name(String),
    /// `{ string: [1, 3] }` or `{ string: from 2 }`.
    String(RawString),
    /// `[int, "8.0.24", bigint]`: the type of the first versions, then each
    /// version from which another type holds, followed by it.
    Periods(Vec<RawShape>),
}

/// Type of a period, in a list of periods.
#[derive(Deserialize)]
#[serde(untagged)]
enum RawShape {
    /// A type name, or a version.
    Name(String),
    /// A string.
    String(RawString),
}

/// String of bytes after some arguments.
#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct RawString {
    /// `[1, 3]` or `from 2`.
    string: RawPositions,
}

/// Positions of arguments, as written in a reference file.
#[derive(Deserialize)]
#[serde(untagged)]
enum RawPositions {
    /// `[1, 3]`.
    At(Vec<usize>),
    /// `from 2`.
    From(String),
}

impl TryFrom<RawShape> for Shape {
    type Error = String;

    fn try_from(raw: RawShape) -> Result<Self, String> {
        match raw {
            RawShape::Name(name) => named(&name).map(Self::Fixed),
            RawShape::String(RawString { string }) => {
                let positions = match string {
                    RawPositions::At(positions)
                        if !positions.is_empty() && !positions.contains(&0) =>
                    {
                        Positions::At(positions)
                    }
                    RawPositions::From(text) => text
                        .strip_prefix("from ")
                        .and_then(|first| first.parse().ok())
                        .filter(|first| *first > 0)
                        .map(Positions::From)
                        .ok_or_else(|| format!("invalid positions {text:?}"))?,
                    RawPositions::At(_) => return Err("positions from 1".to_string()),
                };
                Ok(Self::String(positions))
            }
        }
    }
}

impl TryFrom<RawResultType> for ResultType {
    type Error = String;

    fn try_from(raw: RawResultType) -> Result<Self, String> {
        let first = match raw {
            RawResultType::Name(name) => RawShape::Name(name),
            RawResultType::String(string) => RawShape::String(string),
            RawResultType::Periods(items) => return periods(items),
        };
        Ok(Self {
            first: Shape::try_from(first)?,
            changes: Vec::new(),
        })
    }
}

/// Type per period, from its list: a type, then each version followed by
/// its type, in the order of the versions.
fn periods(items: Vec<RawShape>) -> Result<ResultType, String> {
    let mut items = items.into_iter();
    let first = Shape::try_from(items.next().ok_or("an empty list of types")?)?;
    let mut changes: Vec<(Version, Shape)> = Vec::new();
    while let Some(item) = items.next() {
        let RawShape::Name(text) = item else {
            return Err("a version before each type but the first".to_string());
        };
        let since = Version::parse(&text).ok_or_else(|| format!("invalid version {text:?}"))?;
        if changes.last().is_some_and(|(last, _)| *last >= since) {
            return Err(format!("version {text:?} out of order"));
        }
        let shape = Shape::try_from(items.next().ok_or("a type after each version")?)?;
        changes.push((since, shape));
    }
    if changes.is_empty() {
        return Err("a list of types has a version".to_string());
    }
    Ok(ResultType { first, changes })
}

#[cfg(test)]
mod tests {
    use prisme_plan::Expr;
    use prisme_types::{Type, Value};

    use super::*;

    /// Argument of `data_type`, nullable when `nullable`.
    fn arg(data_type: DataType, nullable: bool) -> Expr {
        Expr::literal_typed(
            Value::Null,
            Type {
                data_type,
                nullable,
            },
        )
    }

    fn version(text: &str) -> Version {
        Version::parse(text).unwrap()
    }

    #[test]
    fn reads_the_forms_of_a_type() {
        let fixed: ResultType = yaml_serde::from_str("int unsigned").unwrap();
        assert_eq!(
            fixed.data_type(&[], version("8.0.11")),
            DataType::Integer(IntegerType::unsigned(IntegerSize::Int))
        );
        let periods: ResultType =
            yaml_serde::from_str(r#"[int, "8.0.24", bigint, "8.1.0", { string: [1] }]"#).unwrap();
        let text = [arg(text_type(), false)];
        for (at, expected) in [
            ("8.0.23", named("int").unwrap()),
            ("8.0.24", named("bigint").unwrap()),
            ("8.0.42", named("bigint").unwrap()),
            ("9.3.0", text_type()),
        ] {
            assert_eq!(periods.data_type(&text, version(at)), expected, "{at}");
        }
        assert_eq!(
            periods.versions().collect::<Vec<_>>(),
            [version("8.0.24"), version("8.1.0")]
        );
        for wrong in [
            "integer",
            "[]",
            "[int]",
            r#"[int, "8.0.24"]"#,
            r#"[int, bigint, "8.0.24"]"#,
            r#"[int, "8.0.24", bigint, "8.0.11", int]"#,
            "{ string: [] }",
            "{ string: [0] }",
            "{ string: from 0 }",
            "{ string: after 1 }",
            "{ string: [1], other: 2 }",
        ] {
            let raw: Result<ResultType, _> = yaml_serde::from_str(wrong);
            assert!(raw.is_err(), "{wrong}");
        }
    }

    #[test]
    fn a_string_is_of_bytes_after_its_arguments() {
        let first: ResultType = yaml_serde::from_str("{ string: [1] }").unwrap();
        let all: ResultType = yaml_serde::from_str("{ string: from 2 }").unwrap();
        let at = version("8.4.0");
        let text = || arg(text_type(), false);
        let bytes = || arg(bytes_type(), false);
        let null = || arg(DataType::Null, true);
        let unknown = || arg(DataType::Unknown, true);
        let hybrid = || {
            arg(
                DataType::Hybrid {
                    length: 1,
                    signed: false,
                },
                false,
            )
        };
        let number = || arg(named("int").unwrap(), false);
        for (shape, args, expected) in [
            (&first, vec![text(), bytes()], text_type()),
            (&first, vec![bytes(), text()], bytes_type()),
            (&first, vec![hybrid()], bytes_type()),
            (&first, vec![number()], text_type()),
            (&first, vec![null()], bytes_type()),
            (&first, vec![unknown()], DataType::Unknown),
            (&all, vec![bytes(), text(), text()], text_type()),
            (&all, vec![number(), text(), null(), bytes()], bytes_type()),
            (&all, vec![number(), unknown(), bytes()], bytes_type()),
            (&all, vec![number(), unknown(), text()], DataType::Unknown),
            (&all, vec![number(), null(), text()], text_type()),
            (&all, vec![number(), null(), null()], bytes_type()),
            (&all, vec![number()], text_type()),
        ] {
            assert_eq!(shape.data_type(&args, at), expected, "{args:?}");
        }
    }

    #[test]
    fn nulls_follow_the_arguments_or_not() {
        let args = [arg(text_type(), false), arg(text_type(), true)];
        assert!(Nulls::Any.nullable(&args[..1]));
        assert!(!Nulls::Args.nullable(&args[..1]));
        assert!(Nulls::Args.nullable(&args));
        assert!(!Nulls::Never.nullable(&args));
    }
}
